import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import Sanscript from 'sanscript';

const LANGUAGE_CODES = ['en', 'hi', 'bn', 'ta', 'te', 'mr'];
const LANGUAGE_LOCALES = {
  en: 'en-IN',
  hi: 'hi-IN',
  bn: 'bn-IN',
  ta: 'ta-IN',
  te: 'te-IN',
  mr: 'mr-IN',
};
const LANGUAGE_SCRIPTS = {
  hi: 'devanagari',
  bn: 'bengali',
  ta: 'tamil',
  te: 'telugu',
  mr: 'devanagari',
};

function transliterateName(name, language) {
  const script = LANGUAGE_SCRIPTS[language];
  if (!name || !script || !/[a-z]/i.test(name) || /[^\p{Script=Latin}\s.'’-]/u.test(name)) return name;
  const itransName = name.toLowerCase().replace(/\bkumar\b/g, 'kumAra');
  try {
    return Sanscript.t(itransName, 'itrans', script, { syncope: true }) || name;
  } catch {
    return name;
  }
}

